proc sql;
   select machine,
          (sum(planned_min) - sum(downtime_min)) / sum(planned_min) as availability format=6.3,
          max(ideal_cycle_s) * sum(total_count) / ((sum(planned_min) - sum(downtime_min)) * 60) as performance format=6.3,
          sum(good_count) / sum(total_count) as quality format=6.3,
          calculated availability * calculated performance * calculated quality as oee format=6.3
   from work.oee_log
   group by machine
   order by oee desc;
quit;
